import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { NativeBridge } from '/Users/jordanknight/pi-hacking/fs3-copilot-native-runtime/.copilot/extensions/pij/store.mjs';
const rows = (await readFile(process.env.PIJ_TRACE,'utf8')).trim().split('\n').map(JSON.parse);
const root=rows.find(e=>e.type==='user.message'); const idle=rows.find(e=>e.type==='session.idle');
const reports=[]; const registration={id:'pij-replay',harness_session:'replay-session',pid:1,proc_start:1};
const bridge=new NativeBridge({registration,native:{send:async()=>root.messageId},client:{request:async()=>1},journal:{load:async()=>undefined,begin:async()=>true,accept:async()=>{}},report:e=>reports.push(e)});
try {
  await bridge.deliver({job_id:1,message:{msg_id:'replay-message',from:'pij-sender',to:'pij-replay',body:'metadata-only replay'},native_consumer:{native_session:'replay-session',pid:1,proc_start:1}});
  let parentKnownBeforeIdle=false;
  for(const e of rows) {if(e.type==='session.idle') parentKnownBeforeIdle=bridge.completion.descendants.has(e.parentId); bridge.completion.observe({type:e.type,id:e.eventId,parentId:e.parentId,agentId:e.agentId,ephemeral:e.ephemeral,data:{messageId:e.messageId,interactionId:e.interactionId,turnId:e.turnId,mode:e.mode}});}
  assert.equal(parentKnownBeforeIdle,true); assert.equal(bridge.completion.terminal?.eventId,idle.eventId);
  await bridge.waitForCompletion();
  assert.equal(reports.filter(e=>e.kind==='native-completed').length,1);
  console.log(JSON.stringify({events:rows.length,parentKnownBeforeIdle,terminal:bridge.completion.terminal,completionReports:1,acknowledgements:reports.filter(e=>e.kind==='inbox-acknowledged').length}));
} finally { bridge.stop(); }
